/* txt.h - story text packs: ids, line records and the decoder.
 *
 * CONTRACT (docs/design/story/SPEC.md sec.4): written by S0, maintained by S2
 * (add-only). Implementation: core/src/txt.c (S2, resident). Packs are
 * generated by core/tools/textpack.py into core/gen/text_*.c (GBA, native)
 * and TEXT.BIN (PS1 build product). Until txt.c lands every function is a
 * weak stub in core/src/stubs.c.
 *
 * Decoding is per string into the caller's buffer (the dialogue queue entry
 * is the buffer), never into a resident copy.
 */
#ifndef DOOMO_TXT_H
#define DOOMO_TXT_H

#include "types.h"

/* Text id = pack:7 | index:9 (SPEC R6): at most 128 packs of 512 strings. */
#define TXT_PACK_BITS   7
#define TXT_INDEX_BITS  9
#define TXT_PACK_MAX    (1 << TXT_PACK_BITS)
#define TXT_INDEX_MAX   (1 << TXT_INDEX_BITS)
#define TXT_ID(pack, index) ((uint16_t)(((unsigned)(pack) << TXT_INDEX_BITS) | ((unsigned)(index) & (TXT_INDEX_MAX - 1))))
#define TXT_PACK(id)    ((int)((unsigned)(id) >> TXT_INDEX_BITS))
#define TXT_INDEX(id)   ((int)((unsigned)(id) & (TXT_INDEX_MAX - 1)))
#define TXT_NONE        0xFFFFu   /* = TXT_ID(127, 511): textpack.py never emits it */

/* Pack caps (bytes, packed; textpack.py fails the build above them). */
#define TXT_CAP_EPISODE  (12u * 1024u)
#define TXT_CAP_COMMON   (6u * 1024u)
#define TXT_CAP_SIDE     (8u * 1024u)
#define TXT_CAP_FEAST    (10u * 1024u)

/* One dialogue line (6 B, in the pack). */
enum { DL_DEADPAN = 1, DL_PUNCH = 2, DL_PILL = 4, DL_SHOUT = 8, DL_HEART = 16,
       DL_GURGLE = 32 };
typedef struct DlgLine {
    int16_t  who;         /* resident id, -2 narrator, -1 player                  */
    uint8_t  expr;        /* EXPR_* (portrait.h)                                   */
    uint8_t  flags;       /* DL_*                                                  */
    uint16_t text;        /* text id                                               */
} DlgLine;

/* Decode text `id` into out (always NUL-terminated). Returns the length, or
 * -1 if the id's pack is not live (out is then ""). */
int  txt_get(uint16_t id, char *out, int cap);
/* Make a pack live (GBA/native: a pointer assignment; PS1: a CD read into
 * the window). 1 ok. */
int  txt_pack_load(int pack);
int  txt_pack_is_live(int pack);
/* The caption stash (SPEC C5): up to 4 decoded lines of 64 B kept resident
 * for a pushed scene (combat captions). */
#define TXT_STASH_LINES 4
#define TXT_STASH_LEN   64
void txt_stash(int slot, uint16_t id);
const char *txt_stash_get(int slot);

/* --- S2: the pack reader (txt.c) and the platform hook --- */
/* Pack kinds (the @pack kind=, the PS1 window slot it loads into). */
enum { TXT_KIND_EPISODE, TXT_KIND_COMMON, TXT_KIND_SIDE, TXT_KIND_FEAST, TXT_KIND_LEGACY };
/* A live pack's bytes, or NULL. GBA / native: core/gen/text_dir.c points
 * into ROM; PS1: ps1/src/txtload.c points into its window. */
const uint8_t *txt_plat_pack(int pack);
/* Make a pack live on the platform (PS1: a CD read). 1 ok. */
int  txt_plat_load(int pack);
/* A script's ops (script id = pack:7 | index:9). NULL if not live. */
const struct StoryOp *txt_script(uint16_t script_id, int *n_ops);
/* A beat script out of a pack (BeatScript in beat.h). 1 ok. */
struct BeatScript;
int  txt_beat(uint16_t beat_id, struct BeatScript *out);
/* Pack stats for tests and the lint. */
int  txt_pack_count(void);
int  txt_pack_strings(int pack);
int  txt_pack_scripts(int pack);
int  txt_pack_beats(int pack);
int  txt_pack_kind(int pack);
int  txt_pack_flags(int pack);
/* The generated directory (core/gen/txt_dict.c). */
extern const uint16_t doomo_txt_npacks;
extern const char doomo_txt_pack_names[][9];
extern const uint8_t doomo_txt_pack_kinds[];
extern const uint8_t doomo_txt_pack_chapters[];
extern const uint16_t doomo_txt_pack_minutes[];
extern const uint16_t doomo_txt_pack_bytes[];
/* --- end S2 --- */

#endif
